const {config}=$input.first().json;
const fecha=$now.setZone('Europe/Madrid').minus({days:1}).toISODate();
for(const k of ['API_BASE_URL','DATAFONO_CSV_URL','CORREO_MARISA','CORREO_REMITENTE'])
  if(typeof config[k]!=='string'||!config[k].trim())throw new Error('Falta configuración de datáfono');
const url=config.DATAFONO_CSV_URL.replaceAll('{fecha}',fecha);
for(const value of [url,config.API_BASE_URL]){
  // Configuración del operador, nunca una URL tomada del CSV.
  if(!/^https?:\/\/[^\s/@?#]+(?::\d+)?(?:\/[^\s?#]*)?$/.test(value))throw new Error('URL de configuración no válida');
}
return [{json:{config,fecha,url}}];

const contexto=$('Fijar día y fuente').first().json;
const text=$input.first().json.csv;
if(typeof text!=='string'||new TextEncoder().encode(text).length>1048576)throw new Error('CSV ausente o demasiado grande');
function parseCSV(s){
  s=s.replace(/^\uFEFF/,'');
  const rows=[];let row=[],field='',quoted=false,closed=false;
  const finish=()=>{row.push(field);field='';closed=false;};
  for(let i=0;i<s.length;i++){
    const c=s[i];
    if(quoted){if(c==='"'){if(s[i+1]==='"'){field+='"';i++;}else{quoted=false;closed=true;}}else field+=c;continue;}
    if(c==='"'){if(field||closed)throw new Error('CSV con comillas inválidas');quoted=true;}
    else if(c===';')finish();
    else if(c==='\r'||c==='\n'){if(c==='\r'&&s[i+1]==='\n')i++;finish();rows.push(row);row=[];}
    else {if(closed)throw new Error('CSV con texto tras comillas');field+=c;}
  }
  if(quoted)throw new Error('CSV con comillas sin cerrar');
  if(field||closed||row.length){finish();rows.push(row);}
  return rows;
}
const rows=parseCSV(text);
const header=['terminal_id','operacion_id','fecha','tipo','concepto','importe','moneda','venta_id'];
if(!rows.length||JSON.stringify(rows.shift())!==JSON.stringify(header))throw new Error('Cabecera CSV no válida');
if(rows.length>2000||rows.some(r=>r.length!==header.length))throw new Error('Estructura o número de filas CSV no válido');
const incidencias=[],map=new Map(),conflictos=new Set();let duplicados=0;
for(let i=0;i<rows.length;i++){
  const r=Object.fromEntries(header.map((k,n)=>[k,rows[i][n].trim()]));
  const motivos=[];
  if(!/^[A-Za-z0-9_-]{1,64}$/.test(r.terminal_id)||!/^[A-Za-z0-9_-]{1,64}$/.test(r.operacion_id))motivos.push('referencia inválida');
  if(r.fecha!==contexto.fecha)motivos.push('fecha fuera del día procesado');
  if(r.tipo!=='venta')motivos.push('no es una venta directa');
  if(r.moneda!=='EUR')motivos.push('moneda distinta de EUR');
  if(!/^\d{1,9}(?:[.,]\d{1,2})?$/.test(r.importe))motivos.push('importe inválido');
  const partes=r.importe.split(/[.,]/);const centimos=Number(partes[0])*100+Number((partes[1]||'').padEnd(2,'0'));
  if(!Number.isSafeInteger(centimos)||centimos<=0)motivos.push('importe no positivo');
  const concepto=r.concepto.replace(/\s+/g,' ').trim();
  if(!concepto||concepto.length>160||/[\x00-\x1f\x7f]/.test(concepto)||concepto.includes('[TPV:'))motivos.push('concepto inválido');
  if(r.venta_id&&!/^[1-9]\d{0,9}$/.test(r.venta_id))motivos.push('venta_id inválido');
  const clave=`datafono:${r.terminal_id}:${r.operacion_id}`;
  if(motivos.length){incidencias.push({fila:i+2,motivo:motivos.join('; ')});conflictos.add(clave);continue;}
  const referencia=`[TPV:${r.terminal_id}:${r.operacion_id}]`;
  const doc={referencia,concepto,centimos,payload:{fecha:r.fecha,concepto:`${referencia} ${concepto}`,importe:centimos/100,forma_pago:'tarjeta'}};
  const op={clave,documento:doc,venta_id:r.venta_id?Number(r.venta_id):null,fila:i+2};
  if(map.has(clave)){
    const previo=map.get(clave);
    if(JSON.stringify(previo.documento)!==JSON.stringify(doc)||previo.venta_id!==op.venta_id){conflictos.add(clave);incidencias.push({fila:i+2,motivo:'referencia repetida con datos distintos'});}
    else duplicados++;
  }else map.set(clave,op);
}
const operaciones=[...map.values()].filter(o=>!conflictos.has(o.clave));
return [{json:{...contexto,operaciones,incidencias,duplicados,filas:rows.length}}];

const lote=$('Validar CSV del datáfono').first().json;
const ventas=$input.first().json.body;
if(!Array.isArray(ventas)||ventas.some(v=>!Number.isInteger(v.id)||!Number.isFinite(v.importe)||typeof v.concepto!=='string'||v.fecha!==lote.fecha))throw new Error('Respuesta de ventas no válida');
const plan=[],incidencias=[...lote.incidencias];
const normal=s=>s.normalize('NFKC').replace(/\s+/g,' ').trim().toLowerCase();
const marcador=s=>/^\[TPV:[A-Za-z0-9_-]{1,64}:[A-Za-z0-9_-]{1,64}\](?: |$)/.test(s);
for(const op of lote.operaciones){
  const d=op.documento;
  const mismas=ventas.filter(v=>v.concepto===d.payload.concepto||v.concepto.startsWith(d.referencia+' ')||v.concepto===d.referencia);
  let existente=null,motivo=null;
  const compatible=v=>v.fecha===lote.fecha&&v.forma_pago==='tarjeta'&&Math.round(v.importe*100)===d.centimos;
  if(mismas.length>1)motivo='más de una venta con la misma referencia';
  else if(mismas.length===1){
    if(!compatible(mismas[0])||mismas[0].concepto!==d.payload.concepto||op.venta_id&&op.venta_id!==mismas[0].id)motivo='referencia existente con datos distintos';
    else existente=mismas[0].id;
  }else if(op.venta_id){
    const v=ventas.find(v=>v.id===op.venta_id);
    if(!v||!compatible(v)||normal(v.concepto)!==normal(d.concepto))motivo='venta_id no corresponde con el cobro';
    else existente=v.id;
  }else if(ventas.some(v=>compatible(v)&&!marcador(v.concepto)))motivo='posible venta manual ya registrada: aportar venta_id o revisar';
  if(motivo)incidencias.push({fila:op.fila,motivo});else plan.push({...op,existente});
}
// Dos referencias diferentes no pueden enlazarse a la misma venta manual.
const repetidos=new Set(plan.filter(o=>o.existente&&plan.filter(p=>p.existente===o.existente).length>1).map(o=>o.existente));
for(const o of plan.filter(o=>repetidos.has(o.existente)))incidencias.push({fila:o.fila,motivo:'dos operaciones enlazadas a la misma venta'});
return [{json:{...lote,plan:plan.filter(o=>!repetidos.has(o.existente)),incidencias}}];

const reserva=$('Reservar operación').item.json;
const v=$input.first().json,p=reserva.documento.payload;
const confirmada=Number.isInteger(v.id)&&v.id>0&&v.fecha===p.fecha&&v.forma_pago==='tarjeta'&&v.concepto===p.concepto&&Number.isFinite(v.importe)&&Math.round(v.importe*100)===Math.round(p.importe*100);
return [{json:{clave:reserva.clave,confirmada,venta_id:confirmada?v.id:null}}];

const lote=$('Planificar ventas sin duplicados').first().json;
const registros=$input.first().json.registros;
const incidencias=[...lote.incidencias];let nuevas=0,existentes=0;
for(const op of lote.plan){
  const r=registros.find(r=>r.clave===op.clave);
  const mismo=r?.documento?.payload&&['concepto','fecha','importe','forma_pago'].every(k=>r.documento.payload[k]===op.documento.payload[k]);
  if(!mismo)incidencias.push({fila:op.fila,motivo:'referencia reservada con otros datos; no se vuelve a importar'});
  else if(r.estado==='confirmado'){if(r.ejecucion===$execution.id&&!op.existente)nuevas++;else existentes++;}
  else incidencias.push({fila:op.fila,motivo:'operación sin confirmación: conciliar en la API antes de cualquier reintento'});
}
const resumen={fecha:lote.fecha,filas:lote.filas,nuevas,existentes,duplicados:lote.duplicados,revision:incidencias.length};
const texto=[`Cobros del datáfono · ${lote.fecha}`,`Ventas nuevas: ${nuevas}`,`Ya registradas: ${existentes}`,`Filas duplicadas del CSV: ${lote.duplicados}`,`Incidencias: ${incidencias.length}`,...incidencias.map(r=>`Fila ${r.fila}: ${r.motivo}`),'','No se importan abonos de apartados ni devoluciones. Si hubo una corrección tardía, revisar el cierre de caja.'].join('\n');
return [{json:{resumen,incidencias,documento:{destinatario:lote.config.CORREO_MARISA,remitente:lote.config.CORREO_REMITENTE,asunto:`Paso Firme · Datáfono ${lote.fecha}: ${nuevas} nuevas, ${incidencias.length} por revisar`,texto}}}];
